function isRepairableFriendlyBuilding(ent,faction){if(!ent||ent.faction!==faction)return false;const repairableTypes=new Set(['base','tower','house','wall','rail','train','harbor','apartment','training','silo','radar']);if(repairableTypes.has(ent.type))return ent.hp<ent.maxHp;if(buildSites.includes(ent)){if(ent.maxHp===undefined)ent.maxHp=buildSiteMaxHp(ent.type);if(ent.hp===undefined)ent.hp=Math.max(1,ent.maxHp*0.02);return ent.hp<ent.maxHp;}
return false;}
function hitTestEnemyEntityStrict(wx,wy){for(let s of buildSites){if(s.faction!=='ai')continue;if(s.maxHp===undefined)s.maxHp=buildSiteMaxHp(s.type);if(s.hp===undefined)s.hp=Math.max(1,s.maxHp*0.02);if(!s.id)s.id=buildSiteId(s);const w=(s.tw||1)*TILE,h=(s.th||1)*TILE;if(wx>=s.x+2&&wx<=s.x+w-2&&wy>=s.y+2&&wy<=s.y+h-2)return s;}for(let b of ai.bases)if(wx>=b.x+4&&wx<=b.x+TILE*2-4&&wy>=b.y+4&&wy<=b.y+TILE*2-4)return b;for(let u of ai.units)if(dist({x:wx,y:wy},u)<11)return u;for(let t of ai.tanks)if(dist({x:wx,y:wy},t)<13)return t;for(let p of (ai.patriots||[]))if(dist({x:wx,y:wy},p)<13)return p;for(let s of (ai.supplies||[]))if(dist({x:wx,y:wy},s)<13)return s;for(let d of ai.drones)if(dist({x:wx,y:wy},d)<7)return d;for(let h of ai.helicopters){const hc=getHelicopterVisualCenter(h);if(dist({x:wx,y:wy},hc)<18)return h;}for(let bk of ai.bikes)if(dist({x:wx,y:wy},bk)<9)return bk;for(let s of ai.ships)if(dist({x:wx,y:wy},s)<15)return s;for(let tw of ai.towers)if(wx>=tw.x+2&&wx<=tw.x+TILE-2&&wy>=tw.y+2&&wy<=tw.y+TILE-2)return tw;for(let wall of ai.walls)if(wx>=wall.x+1&&wx<=wall.x+TILE-1&&wy>=wall.y+1&&wy<=wall.y+TILE-1)return wall;for(let h of ai.houses)if(wx>=h.x+2&&wx<=h.x+TILE-2&&wy>=h.y+2&&wy<=h.y+TILE-2)return h;for(let h of ai.harbors)if(wx>=h.x+2&&wx<=h.x+TILE-2&&wy>=h.y+2&&wy<=h.y+TILE-2)return h;for(let r of(ai.rails||[]))if(wx>=r.x+2&&wx<=r.x+TILE-2&&wy>=r.y+2&&wy<=r.y+TILE-2)return r;for(let c of(ai.cranes||[]))if(wx>=c.x+2&&wx<=c.x+TILE-2&&wy>=c.y+2&&wy<=c.y+TILE-2)return c;for(let s of(ai.silos||[]))if(wx>=s.x+2&&wx<=s.x+TILE-2&&wy>=s.y+2&&wy<=s.y+TILE-2)return s;for(let r of(ai.radars||[]))if(wx>=r.x+2&&wx<=r.x+TILE-2&&wy>=r.y+2&&wy<=r.y+TILE-2)return r;for(let a of(ai.apartments||[]))if(wx>=a.x+2&&wx<=a.x+TILE-2&&wy>=a.y+2&&wy<=a.y+TILE-2)return a;for(let g of(ai.trainings||[]))if(wx>=g.x+2&&wx<=g.x+TILE-2&&wy>=g.y+2&&wy<=g.y+TILE-2)return g;for(let w of ai.workers)if(dist({x:wx,y:wy},w)<11)return w;return null;}
