function endGame(win,customText){if(gameOver)return;gameOver=true;if(cheatPunishment.timer){clearTimeout(cheatPunishment.timer);cheatPunishment.timer=null;}cheatPunishment.active=false;if(MP.active&&!win)MP.send({type:'surrender'});if(MP.active){MP.stopPing();MP.stopSync();}
let msg=document.getElementById('message');const baseText=customText||(win?'⚡ VÍTĚZSTVÍ ⚡':'☠ PORÁŽKA ☠');msg.textContent=baseText;msg.style.color=win&&!customText?'#00ff88':'#ff3344';msg.classList.add('show');setTimeout(()=>{msg.textContent=baseText+'\n[Klikni pro restart]';},1500);}
function updateUI(){document.getElementById('p-res').textContent=Math.floor(player.resources);document.getElementById('p-units').textContent=popUsed('player');document.getElementById('p-bases').textContent=player.bases.length;document.getElementById('a-res').textContent=Math.floor(ai.resources);document.getElementById('a-units').textContent=popUsed('ai');document.getElementById('a-bases').textContent=ai.bases.length;let pcap=popCap('player');document.getElementById('p-cap').textContent=pcap;let acap=popCap('ai');document.getElementById('a-cap').textContent=acap;document.getElementById('btn-base').disabled=player.resources<BASE_COST;document.getElementById('btn-house').disabled=player.resources<HOUSE_COST;document.getElementById('btn-apartment').disabled=player.resources<APARTMENT_COST;document.getElementById('btn-training').disabled=player.resources<TRAINING_COST;document.getElementById('btn-wall').disabled=player.resources<WALL_COST;let railBtn=document.getElementById('btn-rail');if(railBtn)railBtn.disabled=player.resources<RAIL_COST;let stationBtn=document.getElementById('btn-train');if(stationBtn)stationBtn.disabled=player.resources<TRAIN_COST||(player.rails||[]).length===0;let craneBtn=document.getElementById('btn-crane');if(craneBtn){craneBtn.disabled=true;craneBtn.style.display='none';}document.getElementById('btn-tower').disabled=player.resources<TOWER_COST;let superTowerBtn=document.getElementById('btn-super-tower');if(superTowerBtn)superTowerBtn.disabled=player.resources<SUPER_TOWER_COST;let siloBtn=document.getElementById('btn-silo');if(siloBtn)siloBtn.disabled=player.resources<SILO_COST||player.bases.length===0;let radarBtn=document.getElementById('btn-radar');if(radarBtn)radarBtn.disabled=player.resources<RADAR_COST||player.bases.length===0;document.getElementById('btn-unit').disabled=player.resources<UNIT_COST||player.bases.length===0||popUsed('player')>=popCap('player');document.getElementById('btn-worker').disabled=player.resources<WORKER_COST||player.bases.length===0||popUsed('player')>=popCap('player');let _qDroneCount=0,_qLeaderCount=0;for(let qi=0;qi<player.trainQueue.length;qi++){const qt=player.trainQueue[qi].type;if(qt==='drone')_qDroneCount++;else if(qt==='leader')_qLeaderCount++;}const droneCount=player.drones.length+_qDroneCount;let droneBtn=document.getElementById('btn-drone');if(droneBtn)droneBtn.disabled=player.resources<DRONE_COST||player.bases.length===0||droneCount>=DRONE_MAX_PLAYER;let heliBtn=document.getElementById('btn-helicopter');if(heliBtn)heliBtn.disabled=player.resources<HELICOPTER_COST||player.bases.length===0||(popUsed('player')+HELICOPTER_POP_COST>popCap('player'));let tankBtn=document.getElementById('btn-tank');if(tankBtn)tankBtn.disabled=player.resources<TANK_COST||player.bases.length===0||(popUsed('player')+1>popCap('player'));let launcherBtn=document.getElementById('btn-launcher');if(launcherBtn)launcherBtn.disabled=player.resources<LAUNCHER_COST||player.bases.length===0||(popUsed('player')+LAUNCHER_POP_COST>popCap('player'));let leaderBtn=document.getElementById('btn-leader');const leaderTotal=player.leaders.length+_qLeaderCount;if(leaderBtn)leaderBtn.disabled=player.resources<LEADER_COST||player.bases.length===0||leaderTotal>=PLAYER_LEADER_MAX||(popUsed('player')+1>popCap('player'));let harborBtn=document.getElementById('btn-harbor');if(harborBtn)harborBtn.disabled=player.resources<HARBOR_COST;let shipBtn=document.getElementById('btn-ship');if(shipBtn)shipBtn.disabled=player.resources<SHIP_COST||player.harbors.length===0;let patriotBtn=document.getElementById('btn-patriot');if(patriotBtn)patriotBtn.disabled=player.resources<PATRIOT_COST||player.bases.length===0||(popUsed('player')+PATRIOT_POP_COST>popCap('player'));let supplyBtn=document.getElementById('btn-supply');if(supplyBtn)supplyBtn.disabled=player.resources<SUPPLY_COST||player.bases.length===0||(popUsed('player')+SUPPLY_POP_COST>popCap('player'));const _qBuckets={};const _qTypes=['unit','worker','leader','tank','drone','helicopter','ship','launcher','patriot','supply'];for(let i=0;i<_qTypes.length;i++)_qBuckets[_qTypes[i]]=[];for(let i=0;i<player.trainQueue.length;i++){const q=player.trainQueue[i];if(q&&_qBuckets[q.type])_qBuckets[q.type].push(q);}const setQ=(id,type,color)=>{let el=document.getElementById(id);if(!el)return;el.textContent=formatProductionInfo(_qBuckets[type]||[]);el.style.color=color;_qBuckets[type].length=0;};setQ('unit-queue','unit','#00ff88');setQ('worker-queue','worker','#44ddff');setQ('leader-queue','leader','#ffdd44');setQ('tank-queue','tank','#ffaa00');setQ('drone-queue','drone','#cc88ff');setQ('helicopter-queue','helicopter','#88ddff');setQ('ship-queue','ship','#44aaff');setQ('launcher-queue','launcher','#ff6fd1');setQ('patriot-queue','patriot','#ff8c5a');setQ('supply-queue','supply','#9bff8f');}
function forestTreeKind(tx,ty){const nearWater=((tx>0&&map[ty][tx-1]===1)||(tx<MAP_W-1&&map[ty][tx+1]===1)||(ty>0&&map[ty-1][tx]===1)||(ty<MAP_H-1&&map[ty+1][tx]===1));const nearMountain=((tx>0&&map[ty][tx-1]===2)||(tx<MAP_W-1&&map[ty][tx+1]===2)||(ty>0&&map[ty-1][tx]===2)||(ty<MAP_H-1&&map[ty+1][tx]===2));const lat=ty/Math.max(1,MAP_H-1);const h=threeFPHash01(tx,ty,0.77);const h2=threeFPHash01(tx,ty,0.12);let kind='birch';if(nearMountain||lat<0.22)kind=(h<0.58?'spruce':'pine');else if(nearWater||lat>0.78)kind=(h<0.62?'oak':'birch');else{if(h<0.22)kind='pine';else if(h<0.44)kind='spruce';else if(h<0.70)kind='birch';else kind='oak';}
if(h2>0.986&&!nearWater&&!nearMountain)kind='dead';return kind;}
function forestTreeIcon(kind){return kind==='pine'?'🌲':kind==='spruce'?'🎄':kind==='oak'?'🌳':kind==='birch'?'🍃':'🪵';}







